---是否抽到了所有奖励
function WeekGachaponComponent:IsGetAllReward()
    return self.callTaskRewardsAvailableNum == self.callTaskRewardsNum
end

---获取当前id任务的扭蛋次数，不传id取所有
function WeekGachaponComponent:GetGachaponNum(taskId)
    local num = 0
    if isNull(taskId) then
        for k, v in pairs(self.randomTaskList) do
            if checkNumber(v.status) == Constants.GetStatus.Can then
                num = num + checkNumber(v.callNum)
            end
        end
    else
        for k, v in pairs(self.randomTaskList) do
            if checkNumber(v.taskId) == checkNumber(taskId) then
                num = checkNumber(v.callNum)
                return num
            end
        end
    end
    return num
end

---将服务端返回的Map结构处理为用于显示的List结构
function WeekGachaponComponent:RewardsMap2RewardsList()
    self.randomTaskRewardsList = {}
    local group1 = {}
    local group2 = {}
    for k, v in pairs(self.rewardsVoMap) do
        local id = v.reward
        local goodVo = GoodsConfMgr:GetInstance():GetGoodsVoById(id)
        local num = v.rewardNum
        local drawNum = self.randomTaskRewards[checkString(k)]
        local stock = isNull(drawNum) and checkNumber(v.stock) or checkNumber(v.stock) - drawNum
        if (v.type) == 1 then --大奖
            table.insert(group1, {
                voId = v.id,
                quality = goodVo.quality,
                id = id,
                num = num,
                bottomTitle = localize("剩余：")..stock,
            })
        elseif (v.type) == 2 then--参与奖
            table.insert(group2, {
                voId = v.id,
                quality = goodVo.quality,
                id = id,
                num = num,
                bottomTitle = localize("剩余：")..stock,
            })
        end
    end
    --for k, v in pairs(self.randomTaskRewards) do
    --    local vo = self.rewardsVoMap[checkString(k)]
    --    local id = vo.reward
    --    local num = vo.rewardNum
    --    local stock = checkNumber(vo.stock) - checkNumber(v)
    --    if (vo.type) == 1 then --大奖
    --        table.insert(group1, {
    --            id = id,
    --            num = num,
    --            bottomTitle = localize("剩余：")..stock,
    --        })
    --    elseif (vo.type) == 2 then--参与奖
    --        table.insert(group2, {
    --            id = id,
    --            num = num,
    --            bottomTitle = localize("剩余：")..stock,
    --        })
    --    end
    --end
    --printInfo("111=====>>"..table.dump(group1))
    --printInfo("222=====>>"..table.dump(group2))
    table.sort(group1, function (a,b)--按段位进行排序
        if a.quality ~= b.quality then
            return a.quality > b.quality
        end
        return a.voId < b.voId
    end)

    table.sort(group2, function (a,b)--按段位进行排序
        if a.quality ~= b.quality then
            return a.quality > b.quality
        end
        return a.voId < b.voId
    end)

    table.insert(self.randomTaskRewardsList, group1)
    table.insert(self.randomTaskRewardsList, group2)
end

---计算抽奖次数（分子）
function WeekGachaponComponent:CalculateTaskRewardsNum()
    local num = 0
    for k, v in pairs(self.randomTaskRewards) do
        --local vo = self.rewardsVoMap[checkString(k)]
        --local stock = checkNumber(vo.stock) - checkNumber(v)
        num = num + checkNumber(v)
    end
    self.callTaskRewardsNum = num
end

function WeekGachaponComponent:HasUnclaimedGachapon()
    for k, v in pairs(self.randomTaskList) do
        if checkNumber(v.status) == Constants.GetStatus.Can then
            return true
        end
    end
    return false
end

---维护任务的数据
---@param id number 任务id
function WeekGachaponComponent:MaintainTaskData(id)
    if isNull(id) then
        for k, v in pairs(self.randomTaskList) do
            if checkNumber(v.status) == Constants.GetStatus.Can then
                self.randomTaskList[k].status = Constants.GetStatus.Has
            end
        end
    else
        for k, v in pairs(self.randomTaskList) do
            if checkNumber(v.taskId) == checkNumber(id) then
                self.randomTaskList[k].status = Constants.GetStatus.Has
                break
            end
        end
    end
    self:SortTaskData()
end

function WeekGachaponComponent:SortTaskData()
    local canList = {}
    local notList = {}
    local getList = {}
    for k, v in pairs(self.randomTaskList) do
        if v.status == Constants.GetStatus.Can then
            table.insert(canList, v)
        elseif v.status == Constants.GetStatus.Not then
            table.insert(notList, v)
        elseif v.status == Constants.GetStatus.Has then
            table.insert(getList, v)
        end
    end
    self.randomTaskList = {}
    for k, v in pairs(canList) do
        table.insert(self.randomTaskList, v)
    end
    for k, v in pairs(notList) do
        table.insert(self.randomTaskList, v)
    end
    for k, v in pairs(getList) do
        table.insert(self.randomTaskList, v)
    end
end

function WeekGachaponComponent:OpenRewardsPoolDialog()
    UIModule.OpenDialog(
            {
                id = Constants.UITypeIds.WeekTasksRewardPreviewDialog,
                parameters = {
                    rewards = self.randomTaskRewardsList,
                    titleList = {
                        localize("本期大奖"),
                        localize("参与奖"),
                    } }
            }
    )
end

return WeekGachaponComponent